content.text:
{
 "包": "J040",
 "答案": [
  {
   "题": "题01",
   "最符合": "B",
   "排序": [
    "B",
    "D",
    "A",
    "C"
   ],
   "理由": {
    "A": "有生有祖业，但命宫武官星、刚强、身在财帛「老是要去赚钱」、私人企业或自己做事业，与「不可能自己做生意」不合；夫妻宫离婚二婚，与「只有娶老婆娶对了」矛盾。",
    "B": "父母宫大财星、父母从商、父母给财禄、生有祖业、大吉，正合出身豪门享祖业；命宫正财、帮人做事领薪水、不会当官、没有抗力、消极抵抗，合「不可能自己做生意」与「没有戒心」；夫妻宫文武双全、当老板、声名远播，合太太能干值得感谢；惟身宫多婚稍有出入。",
    "D": "命宫生有祖业、太太娶得好、帮人做事领薪水、大怒之下犯大错，部分相符；但整体为武官化将、威震边疆、有生杀之权的军人格局，父母宫离散父母、横财、更凶而非豪门巨富，且夫妻宫婚姻毁一半、福德婚姻不好，与「只有娶对老婆」自相矛盾。",
    "C": "命宫个性强、公正廉明、事业做得很大并以「她」称之，与本人情形不合；夫妻身宫太太聒噪吵不停、大打出手、很累，与「最该感谢太太」直接矛盾；田宅破祖业亦不合。"
   }
  }
 ]
}

{
 "包": "J173",
 "答案": [
  {
   "题": "题01",
   "最符合": "C",
   "排序": [
    "C",
    "B",
    "A",
    "D"
   ],
   "理由": {
    "A": "命宫正财帮人做事领薪水、夫妻宫吵架大打出手、福德一世不顺与陈述有合，但本人各宫缺专业技术专长，官禄断没有官带不会当官与掌权做主管不合，福德多婚与认了不离婚相矛盾。",
    "B": "官禄身宫与财帛、迁移都断专业技术专长、离乡走天下，夫妻宫刚强拗狠与太太翻脸相合；但命宫断做生意当老板、自己做事业、位高无权不想权位，与领固定薪水又掌权做主管不合。",
    "C": "命宫文武双全、专业技术专长、科甲重读书，官禄一考就上金榜题名，身宫在迁移出外地读书、到外地发展一去不回，有生杀之权对应掌权，福德一世不顺很累对应在劫难逃，命宫婚姻好招美妻对应他自己觉得好；夫妻宫温和厚道与太太翻脸略有出入，但整体最合。",
    "D": "正财帮人做事领薪水、自己决定婚姻、与父亲相隔有合；但断文官带公家单位银行界、巨贾大富富可敌国，与在私人公司领固定薪水不合，专业技术专长只在父母宫，夫妻婚姻凶横祸也与他认了觉得好的婚姻不合。"
   }
  }
 ]
}

{
 "包": "J018",
 "答案": [
  {
   "题": "题01",
   "最符合": "B",
   "排序": [
    "B",
    "D",
    "C",
    "A"
   ],
   "理由": {
    "A": "夫妻宫配偶厚道温和、奔波，与丈夫出外在外奔波略合，但婚姻只断「后天受婚姻影响大」，没有分离、聚少离多之象，与34岁后无夫、必然分开的陈述对不上。",
    "B": "命宫直接断「聚少散多」「做偏房」「六亲不靠」，夫妻宫断孤单、停滞、婚姻受该宫之人左右、配偶意外横祸、须注意配偶安危，仆役宫又有「没有名分的先生」，与33岁前分开、34岁后看不到丈夫、丈夫聚少散多的陈述高度相符。",
    "C": "夫妻宫配偶武官星、奔波、吃苦耐劳并提醒配偶健康安危，与丈夫在外（海员）、婚姻有变略合，但主轴在本人佐才、不得重用，婚姻分离之象不如B明确。",
    "D": "身宫福德断「多婚」，命宫断「不容易遇到好的」、配偶「吉处藏凶、在劫难逃」，暗合夫妻分开，但配偶拼命做事、善于理财、温和善良，并无聚少散多在外之象，整体以本人文武官格、领导者为主，与陈述只谈婚姻分离的侧重不同。"
   }
  }
 ]
}

{
 "包": "J069",
 "答案": [
  {
   "题": "题01",
   "最符合": "B",
   "排序": [
    "B",
    "A",
    "D",
    "C"
   ],
   "理由": {
    "A": "命宫正财「帮人做事领薪水」与健康项「开刀、见血光、刃开血光、注意本人健康」、夫妻宫「忌由先生而来、受母亲影响」能对上中风与婆媳问题，但路线断为公家单位、银行界、公务员、当官，又有大富大贵富可敌国，与「私人企业当助手」相悖，且仆役宫「没有名分的先生」显示是女命盘。",
    "B": "命宫正财→帮人做事领薪水，官禄宫「没有官带、不会当官、当官不容易」正合「到私人公司领薪水当助理」；夫妻宫文官带、官带、正财、能言善道、当校长，正是「太太能力非常强」；福德宫「一世不顺、很累、福德宫凶」符合晚年瘫痪受人照顾的处境；只是未直接写出本人中风血光。",
    "D": "有「半空折翅、非常凶、后天受婚姻影响大、婚姻受该宫之人左右」可联系到中风后靠太太照顾，但路线为作家画家、专业技术、离祖外地发展而非辅佐领薪，又有「做偏房、母亲待她好」属女命盘，与本人为丈夫不合。",
    "C": "命宫武官星、化将、威震边疆、大吉、男命最好、生杀之权，走的是武职将领路线，与「领薪水当助手、私人公司做事」完全相反；夫妻宫配偶最好勉强合太太能干，但整体最不符。"
   }
  }
 ]
}

{
 "包": "J008",
 "答案": [
  {
   "题": "题01",
   "最符合": "B",
   "排序": [
    "B",
    "A",
    "C",
    "D"
   ],
   "理由": {
    "A": "财帛「领导力很强、能做事业」、身宫在夫妻「后天受婚姻影响大」与事业好、重婚姻相符，父母宫「很凶」可对应早失父；但命宫「人和、性阴」与「很刚很硬」不合，子女宫「一子、二子、子女宫没问题」与「没有子女」直接矛盾，且无迁移凶之断。",
    "B": "命宫「刚强、孤僻、男人的命、女命最忌」正合「个性很刚很硬」，迁移宫「意外灾、横祸」正合「外地凶、本地吉」，命宫「不得重用、火大不干」与「不屈居人下自己做事业」相符，官禄（身宫）「大吉、金榜题名」可对应事业好；不足处是子女宫「先有孩子」与无子不合，父母宫吉与早年丧父不合。",
    "C": "子女宫「无子」与「没有子女」相符，父母宫「吉处藏凶、在劫难逃」可对应早失父，命宫「个性强」勉强合刚硬；但命宫「正财→帮人做事领薪水、当公务员」与自己创业相反，福德「一世不顺、很累」、财帛「破财」与「钱财事业都很好」直接矛盾。",
    "D": "财帛「领导力很强、能做事业」、官禄「工作顺利」可对应钱财事业好；但命宫「厚道、善良、温和、未言先笑」与「很刚很硬」相反，「佐才→帮人做事领薪水、当助理秘书、位高无权」与自己出来做事业矛盾，子女「无子／没问题」两说不定，父母宫「喜庆、凶得化解」也不合早年丧父。"
   }
  }
 ]
}

{
 "包": "J157",
 "答案": [
  {
   "题": "题01",
   "最符合": "C",
   "排序": [
    "C",
    "B",
    "D",
    "A"
   ],
   "理由": {
    "A": "命宫武官星、刚强刚烈、不苟言笑、厚重，与陈述中性情柔和、才艺博得女孩子欢心的本人大相径庭；夫妻宫斯文温和、配偶最好、婚姻好，与娶三个太太、第二任太太去世不合，仅父母宫才艺文笔好略合，相符最少。",
    "B": "命宫桃花、次桃花、温和厚道谦和、未言先笑，与性情柔和讨女孩子喜欢相合，兄弟父母宫作家画家与才艺相近；但命宫清秀瘦高与长得不见得好看不合，夫妻宫婚姻好、妻长、大吉与三次婚姻、丧妻明显矛盾。",
    "C": "命宫个子矮、皮肤黑、肥胖，与长得不见得好看相合；个性平和聪明、不干武官走文路线，身宫官禄才艺很好、专业技术专长、自由业，夫妻宫二婚、才艺文笔好，仆役宫桃花、作家画家，与多次婚姻、才艺画画文笔、受女子喜欢相合；命宫与子女宫官司是非对应官司纠纷，金榜题名、家财万贯、适得其所对应后来一路顺到老，相符最多。",
    "D": "命宫桃花命、正科桃花星与受女孩子欢迎相合，夫妻身宫作家画家、终不美、福德婚姻不好与婚姻不顺、才艺相近；但命宫刚强、拗、狠、意气用事、魁梧高大，与性情柔和、不好看不合，半空折翅也与晚年一直顺遂矛盾。"
   }
  }
 ]
}

{
 "包": "J101",
 "答案": [
  {
   "题": "题01",
   "最符合": "A",
   "排序": [
    "A",
    "D",
    "B",
    "C"
   ],
   "理由": {
    "A": "命宫教星＋文官带推出当老师、当公务员、公家单位，官禄身宫断当官，仆役宫声名远播，婚姻断婚事不成，子女宫断无子，与校长、官路教育、终身未婚、无儿子高度吻合；仅佐才位高无权、帮人做事与「不屈居人下」稍有出入。",
    "D": "官禄与身宫（夫妻）皆断当老师、文官带、当官、领导力很强、得正位，婚姻凶、孤单亦与未婚相近；但子女宫断一子二子、子女宫没问题，父母宫断早婚、婚姻无事，与无子、终身未婚矛盾。",
    "B": "命宫断当官、不做生意，财帛宫领导力很强，与官路教育及能力强相符；但婚姻断做偏房、先生比她差、聚少散多，预设有丈夫，与一直未婚矛盾，且官禄断没有官带不会当官。",
    "C": "命宫主见强、刚强、男人的命、不屈居人下的气势相符，父母宫有当老师、声名远播；但命宫明断会结婚、婚姻好、招贵夫，子女宫断一子，与终身未婚、生不到儿子直接矛盾。"
   }
  }
 ]
}

{
 "包": "J044",
 "答案": [
  {
   "题": "题01",
   "最符合": "A",
   "排序": [
    "A",
    "D",
    "B",
    "C"
   ],
   "理由": {
    "A": "命宫正财→帮人做事领薪水、官禄宫私人企业做事、夫妻宫（身宫）专业技术专长且后天受婚姻影响大、婚姻不好，福德宫不同意离婚，命宫吉处藏凶→在劫难逃，成败孤军奋战，几乎逐条对上陈述；仅「佐才位高无权」与「掌权做主管」略有出入。",
    "D": "正财领薪水、官禄身宫做主管掌权、科甲才艺博学与陈述的上班做主管、学业有成相符；但夫妻宫断二婚离婚，与「不会离婚、认了」直接矛盾，且断巨贾、事业做得很大、富可敌国与领固定薪水不合。",
    "B": "命宫做主管、专业技术专长、科甲重读书与陈述的主管、专长、学业有成相符，夫妻宫后天受婚姻影响大、夫妻吵架也沾边；但无私人企业领薪水之断，官禄断当老师作家，且多处以「她」称呼、强调婆媳母亲，与陈述取向不同。",
    "C": "正财帮人做事领薪水、夫妻宫受婚姻影响大、夫妻吵架与陈述部分相符；但断公家单位、巨贾富可敌国、大利外地经商，没有做主管与专业技术专长之断，在劫难逃落在父母宫而非本人，相符度最低。"
   }
  }
 ]
}

{
 "包": "J026",
 "答案": [
  {
   "题": "题01",
   "最符合": "D",
   "排序": [
    "D",
    "C",
    "A",
    "B"
   ],
   "理由": {
    "A": "命宫武官星刚强、子女宫无子、与父亲相隔与陈述相符，但长相断为瘦高高挑，与「个子很小」直接矛盾，且全盘不见偏房格，个性还带厚道温和谦和，与泼妇骂街的凶悍不合。",
    "B": "命宫断为公正廉明、厚道、一世荣华、事业做得很大，父母宫旺父母孝顺家里、田宅生有祖业，与被领养见不到父母、无家、凶恶泼辣的陈述几乎处处不合，仅个性强、先生不好略沾边。",
    "C": "命宫偏房格、做偏房、个子矮形小、唠叨太吵能言善道、男人受不了，与做偏房、个子小、骂街相符；但命宫个性断为平和，子女宫断一子二子、先有孩子，与「为人凶恶刚强」「没有子女」矛盾。",
    "D": "命宫偏房格、做偏房、进偏房的大运，娇小玲珑形小，加上武官星刚强、大怒之下犯大错、是非口舌、唠叨太吵、男人受不了、女命最忌，身宫在财帛断不做家庭主妇、老是要去赚钱，与做偏房、个子小、凶悍泼辣、没有家庭观念高度相符；不足处是子女宫断没问题、先有孩子，与无子女不合，也未明断领养。"
   }
  }
 ]
}

{
 "包": "J141",
 "答案": [
  {
   "题": "题01",
   "最符合": "C",
   "排序": [
    "C",
    "B",
    "A",
    "D"
   ],
   "理由": {
    "A": "仆役宫有「朋友变仇人、凶灾」勉强对上合伙生祸，但夫妻宫断「配偶最好、婚姻无事」，与她多次婚姻、每段只维持7年明显矛盾，也无出外海外之象。",
    "B": "迁移身宫断到外地海外发展、一去不回，与人在加州相符；仆役「朋友变仇人」亦合，婚姻只断「难有着落、婆媳不和」而非屡次离异，子女宫以男性刚强为主，与儿子女性化不甚相符。",
    "C": "夫妻宫直断「二婚、离婚」、福德「婚姻不好」，正合每段婚姻只维持7年；仆役宫「朋友变仇人、官司、是非」正合与朋友合伙必以打官司收场；子女宫无子、凶、不能解厄亦可对应子女异常，唯缺迁移海外及声音沙哑的直接对应。",
    "D": "仆役宫断「人和、合伙吉」，与合伙必打官司直接相反；婚姻只断配偶刚强、妻长，无离异之象；仅迁移海外一点相符，整体最不符。"
   }
  }
 ]
}

{
 "包": "J228",
 "答案": [
  {
   "题": "题01",
   "最符合": "C",
   "排序": [
    "C",
    "A",
    "B",
    "D"
   ],
   "理由": {
    "A": "夫妻宫断配偶奔波、属军人到边疆之类、要特别注意配偶安全，兄弟宫又见水中作冢、离乡走天下，与丈夫在外聚少、最终分开尚能呼应，但没有明确的离婚或聚少散多之断，且未按女命论。",
    "B": "夫妻宫直接断二婚、离婚，与分开相符；但配偶被断为公务员、老师、领导力强的安稳之人，没有聚少散多或在外奔波的迹象，与海员型丈夫不符。",
    "C": "命宫明断聚少散多、先生比她差、嫁同龄初婚者凶、一个人持家、不靠男人，夫妻宫又断二婚离婚，全盘按女命论述，与陈述的丈夫长年在外、最终分开几乎逐条相符，最为符合。",
    "D": "以女命论，夫妻宫断吵架大打出手、要特别注意配偶安全、婆媳不和、福德凶，分开有可能，但重点在婆媳与争吵，没有聚少散多、丈夫在外奔波之断，相符较少。"
   }
  }
 ]
}

{
 "包": "J086",
 "答案": [
  {
   "题": "题01",
   "最符合": "B",
   "排序": [
    "B",
    "D",
    "A",
    "C"
   ],
